import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
API_SECRET = os.environ.get('API_SECRET', 'default-dev-key')

os.makedirs(UPLOAD_DIR, exist_ok=True)

def verify_request(req):
    """Verify API request signature using HMAC-SHA256"""
    provided_sig = req.headers.get('X-Signature', '')
    timestamp = req.headers.get('X-Timestamp', '')
    body = req.get_data()
    expected = hmac.new(API_SECRET.encode(), timestamp.encode() + body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(provided_sig, expected)

def sanitize_filename(name):
    """Remove path traversal attempts"""
    name = secure_filename(name)
    if not name:
        name = 'unnamed_file'
    return name

def get_conversion_format(fmt):
    """Validate output format"""
    allowed = ['pdf', 'png', 'jpg', 'svg', 'eps']
    if fmt.lower() in allowed:
        return fmt.lower()
    return None

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to requested format using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')
    page_range = request.form.get('pages', '')

    validated_format = get_conversion_format(output_format)
    if not validated_format:
        return jsonify({'error': 'Unsupported format'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    # Build conversion command
    output_dir = tempfile.mkdtemp(prefix='conv_')

    cmd = f'libreoffice --headless --convert-to {validated_format}'

    if page_range:
        # Allow user to specify page range for partial conversion
        cmd += f' --outdir {output_dir} -env:UserInstallation=file:///tmp/lo_profile '
        cmd += f'--infilter="PageRange={page_range}" '
    else:
        cmd += f' --outdir {output_dir} '

    cmd += f'"{input_path}"'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=output_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'detail': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find output file
        output_files = os.listdir(output_dir)
        if not output_files:
            return jsonify({'error': 'No output generated'}), 500

        output_path = os.path.join(output_dir, output_files[0])
        return send_file(output_path, as_attachment=True)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v2/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON manifest"""
    manifest = request.get_json()
    if not manifest or 'files' not in manifest:
        return jsonify({'error': 'Invalid manifest'}), 400

    results = []
    for entry in manifest['files'][:10]:  # Limit to 10 files
        source_url = entry.get('url', '')
        # Only allow internal S3 presigned URLs
        if not source_url.startswith('https://s3.'):
            results.append({'status': 'rejected', 'reason': 'invalid source'})
            continue
        results.append({'status': 'queued', 'url': source_url})

    return jsonify({'batch_id': hashlib.md5(str(manifest).encode()).hexdigest(), 'results': results})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
